def transform_remove_matching(grid):
    result = [row[:] for row in grid]
    # Define block regions
    blocks = {
        4: [(r,c) for r in range(2,5) for c in range(6,9)],
        7: [(r,c) for r in range(12,15) for c in range(0,3)],
        8: [(r,c) for r in range(7,10) for c in range(13,16)]
