def find_all_solid_rectangles(grid):
    """Find all maximal solid rectangles of the same color."""
    h, w = len(grid), len(grid[0])
    rectangles = []

    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] != 0:
                # Find the maximal rectangle starting at (r1, c1)
                r2, c2 = r1, c1
                while r2 + 1 < h:
                    all_same = True
                    for c in range(c1, c2 + 1):
                        if grid[r2 + 1][c] != grid[r1][c1]:
                            all_same = False
                    if not all_same:
                        break
                    r2 += 1
                while c2 + 1 < w:
                    all_same = True
                    for r in range(r1, r2 + 1):
                        if grid[r][c2 + 1] != grid[r1][c1]:
                            all_same = False
                    if not all_same:
                        break
                    c2 += 1
                # Store unique rectangles
                rect = (r1, c1, r2, c2)
                # Check if already found
                is_new = True
                for existing in rectangles:
                    if existing[0] == r1 and existing[1] == c1:
                        if existing[2] == r2 and existing[3] == c2:
                            is_new = False
                            break
                if is_new and (r2 - r1 + 1 >= 2 and c2 - c1 + 1 >= 2):  # At least 2x2
                    rectangles.append(rect)
                break
            if grid[r1][c1] == 0:
                break
        # Check if all remaining are 0
        if all(grid[r][c1] == 0 for r in range(r1, h)):
            break

    return rectangles

