# What if we need to find 3x3 AND larger solid blocks?

def find_3x3_or_larger_blocks(grid):
    h, w = len(grid), len(grid[0])
    blocks = {}

    for r in range(h - 2):
        for c in range(w - 2):
            # Check if 3x3 is solid
            block_val = grid[r][c]
            if block_val != 0:
                is_solid = True
                for dr in range(3):
                    for dc in range(3):
                        if grid[r+dr][c+dc] != block_val:
                            is_solid = False
                if is_solid:
                    if r not in blocks or c not in blocks[r]:
                        blocks[(r,c)] = block_val

    return blocks

